from billing.api import parse_row
import billing.api as api
assert parse_row("widget,10,USD") == {"name":"widget","cents":"10","currency":"USD"}
assert parse_row("widget,10") == {"name":"widget","cents":"10","currency":""}
assert parse_row("widget") == {"name":"widget","cents":"","currency":""}
try:
    parse_row("widget,10", strict=True)
except ValueError:
    pass
else:
    raise AssertionError("strict did not raise")
assert not hasattr(api, "parse")
from billing.alpha import describe_alpha
assert describe_alpha("widget,10,USD") == "alpha: widget 10 USD"
print("all behavior checks passed")

